#include <iostream>
#include <vector>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        a[i] = i + 1;
    }

    // 枚举步长 d 从 1 到 n-1
    for (int d = 1; d < n; ++d) {
        // 计算需要取出的元素个数
        int cnt = (n - (d - 1) - 1) / d + 1;
        if (cnt < 2) continue;

        // 取出这些位置上的数字
        vector<int> tmp(cnt);
        int idx = 0;
        for (int i = d - 1; i < n; i += d) {
            tmp[idx++] = a[i];
        }

        // 循环右移一位：最后一个元素移到最前面
        int last = tmp[cnt - 1];
        for (int i = cnt - 1; i > 0; --i) {
            tmp[i] = tmp[i - 1];
        }
        tmp[0] = last;

        // 放回原数组
        idx = 0;
        for (int i = d - 1; i < n; i += d) {
            a[i] = tmp[idx++];
        }
    }

    // 输出结果
    for (int i = 0; i < n; ++i) {
        cout << a[i];
        if (i < n - 1) cout << ' ';
    }
    cout << '\n';

    return 0;
}
